<?php
require __DIR__.'/includes/bootstrap.php';require_role(['inspector','officer','admin']);
$page_title='Реестр штрафов';$filter=trim((string)($_GET['q']??''));$bankFilter=(string)($_GET['bank']??'');$sql='SELECT f.*,v.plate,v.make,v.model,v.owner_name,v.owner_email,u.full_name AS issuer FROM fines f JOIN vehicles v ON v.id=f.vehicle_id LEFT JOIN users u ON u.id=f.issued_by WHERE 1=1';$args=[];if($filter!==''){$sql.=' AND (f.external_ref LIKE ? OR v.plate LIKE ? OR v.owner_name LIKE ? OR f.title LIKE ?)';$like='%'.$filter.'%';array_push($args,$like,$like,$like,$like);}if(in_array($bankFilter,['sent','error','pending','not_configured'],true)){$sql.=' AND f.bank_status=?';$args[]=$bankFilter;}$sql.=' ORDER BY f.created_at DESC LIMIT 300';$s=$pdo->prepare($sql);$s->execute($args);$fines=$s->fetchAll();
include __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow">Служебный раздел</span><h1>Реестр штрафов</h1><p>Постановления, история передачи начислений и повторная отправка в банк.</p></section>
<div class="toolbar"><form method="get" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><div class="field"><input name="q" value="<?= e($filter) ?>" placeholder="Номер, госномер, владелец…" aria-label="Поиск штрафа"></div><select class="input" name="bank" aria-label="Статус банка" style="width:auto;min-width:160px"><option value="">Все статусы банка</option><?php foreach(['sent'=>'Передан в банк','error'=>'Ошибка отправки','pending'=>'Ожидает отправки','not_configured'=>'Банк не настроен'] as $k=>$label): ?><option value="<?= e($k) ?>" <?= $bankFilter===$k?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="btn btn-ghost" type="submit">Фильтр</button></form><?php if(has_role(['officer','admin'])): ?><a class="btn btn-primary" href="issue_fine.php">＋ Оформить штраф</a><?php endif; ?></div>
<section class="panel"><div class="panel-header"><h2>Постановления</h2><p>Показано записей: <?= count($fines) ?> (максимум 300)</p></div><?php if($fines): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Постановление</th><th>Автомобиль</th><th>Владелец</th><th>Сумма</th><th>Срок оплаты</th><th>Статус банка</th><th>Действие</th></tr></thead><tbody><?php foreach($fines as $f): ?><tr><td><strong><?= e($f['external_ref']) ?></strong><br><span class="muted tiny"><?= e($f['title']) ?></span></td><td><a href="vehicle.php?id=<?= (int)$f['vehicle_id'] ?>" style="color:#85baff"><?= e($f['plate']) ?></a><br><span class="muted tiny"><?= e($f['make'].' '.$f['model']) ?></span></td><td><?= e($f['owner_name']) ?><br><span class="muted tiny"><?= e($f['owner_email']) ?></span></td><td><strong><?= money($f['amount']) ?></strong><br><span class="muted tiny"><?= e(status_label($f['status'])) ?></span></td><td><?= e($f['due_date']) ?></td><td><span class="badge <?= $f['bank_status']==='sent'?'badge-green':($f['bank_status']==='error'?'badge-red':'badge-yellow') ?>"><?= e(status_label($f['bank_status'])) ?></span><?php if($f['bank_last_error']): ?><br><span class="muted tiny" title="<?= e($f['bank_last_error']) ?>"><?= e(mb_substr($f['bank_last_error'],0,70)) ?></span><?php endif; ?></td><td><?php if($f['bank_status']!=='sent' && $f['status']==='issued' && has_role(['officer','admin'])): ?><form method="post" action="retry_bank.php" class="inline-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="fine_id" value="<?= (int)$f['id'] ?>"><button class="btn btn-ghost btn-small" type="submit" data-confirm="Повторно отправить это начисление в банк?">Повторить</button></form><?php else: ?><span class="muted tiny">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">₽</div><h2>Штрафы не найдены</h2><p>Измените фильтр или оформите первое постановление.</p><?php if(has_role(['officer','admin'])): ?><a class="btn btn-primary" href="issue_fine.php">Оформить штраф</a><?php endif; ?></div><?php endif; ?></section>
<?php include __DIR__.'/includes/footer.php'; ?>
